add_action( 'post_submitbox_misc_actions', 'perfectpixel_draft_product_url' );

function perfectpixel_draft_product_url( $post ) {
	if ( 'product' !== $post->post_type || 'publish' === $post->post_status || ! function_exists( 'get_sample_permalink' ) ) {
		return;
	}
	list( $template, $name ) = get_sample_permalink( $post->ID );
	if ( ! $name ) {
		return; // No slug yet: save the draft first.
	}
	$url = str_replace( array( '%pagename%', '%postname%' ), $name, $template );
	echo '<div class="misc-pub-section"><label for="perfectpixel-draft-url">URL:</label> ';
	echo '<input id="perfectpixel-draft-url" type="text" readonly class="widefat" onclick="this.select()" value="' . esc_attr( $url ) . '"></div>';
}
